script.source:
def path = ctx.containsKey('request_uri') && ctx.request_uri != null ? ctx.request_uri.toString() : '';
def args = ctx.containsKey('args') && ctx.args != null ? ctx.args.toString() : '';
def ua   = ctx.containsKey('http_user_agent') && ctx.http_user_agent != null ? ctx.http_user_agent.toString() : '';
def full = path + ' ' + args;
def statusStr = ctx.containsKey('status') && ctx.status != null ? ctx.status.toString() : '0';
def code = 0;
try { code = Integer.parseInt(statusStr); } catch (Exception e) {}

ctx.soc = [:];
ctx.soc.severity = 'low';
ctx.soc.attack_class = 'none';
ctx.soc.confidence = 0.0;

if (full.matches("(?i).*(\\bselect\\s+.+from\\s+|union\\s+select|\\bselect\\s+\\*\\s+from|sleep\\s*\\(|0x|information_schema|\\bor\\s+1=1|benchmark\\s*\\(|load_file|outfile).*")) {
  ctx.soc.attack_class = 'sqli'; ctx.soc.severity = 'high'; ctx.soc.confidence = 0.85;
}
else if (full.matches("(?i).*(<script|alert\\s*\\(|javascript\\s*:|onerror\\s*=|onload\\s*=|prompt\\s*\\(|confirm\\s*\\(|document\\.cookie|iframe\\s*src).*")) {
  ctx.soc.attack_class = 'xss'; ctx.soc.severity = 'medium'; ctx.soc.confidence = 0.8;
}
else if (full.matches("(?i).*(\\.\\./\\.\\./|\\.\\.%2f|%2e%2e%2f|/etc/passwd|/etc/shadow|windows/system32|\\.\\.\\\\)\\.\\.).*")) {
  ctx.soc.attack_class = 'path_traversal'; ctx.soc.severity = 'high'; ctx.soc.confidence = 0.9;
}
else if (full.matches("(?i).*((\\||;|`|\\$\\()\\s*(cat|id|whoami|ls|wget|curl|nc|bash|sh|python|perl|rm|uname)\\b|/bin/sh|cmd\\.exe|powershell).*")) {
  ctx.soc.attack_class = 'command_injection'; ctx.soc.severity = 'critical'; ctx.soc.confidence = 0.85;
}
else if (full.matches("(?i).*(/\\.env|/\\.git|/\\.aws|/\\.ssh|web\\.config|\\.bak\\b|config\\.php\\b|phpinfo|/dump\\.sql|/backup).*")) {
  ctx.soc.attack_class = 'info_disclosure'; ctx.soc.severity = 'critical'; ctx.soc.confidence = 0.9;
}
else if (full.matches("(?i).*(url=\\s*https?://|proxy=|request=|dest=|target=|uri=\\s*\\d+\\.\\d+\\.\\d+\\.\\d+|file=\\s*https?://|load=\\s*https?://).*")) {
  ctx.soc.attack_class = 'ssrf'; ctx.soc.severity = 'high'; ctx.soc.confidence = 0.7;
}
else if (full.matches("(?i).*(/admin|/manager|/wp-admin|/console|/jenkins|/actuator|/webui/|/geoserver/web|/owa|/exchange|/webmail|/\\.ssh|/phpmyadmin).*")) {
  ctx.soc.attack_class = 'admin_panel_scan'; ctx.soc.severity = 'medium'; ctx.soc.confidence = 0.6;
}
else if (full.matches("(?i).*(login|signin|auth|j_spring_security|logon|authenticate).*")) {
  ctx.soc.attack_class = 'auth_scan'; ctx.soc.severity = 'medium'; ctx.soc.confidence = 0.5;
}
else if (full.matches("(?i).*(sqlmap|nuclei|nikto|gobuster|dirbuster|acunetix|nessus|wpscan|zap|masscan|fuzz|hydra|libwww-perl|python-requests).*")) {
  ctx.soc.attack_class = 'scanner'; ctx.soc.severity = 'low'; ctx.soc.confidence = 0.7;
}

if (ctx.soc.attack_class != 'none' && code >= 400) {
  ctx.soc.confidence = Math.min(0.95, ctx.soc.confidence + 0.1);
}
